package ru.eyeone.relaybridge;

import android.content.Context;

/** Versioned, affirmative consent. No collection is enabled by opening the app. */
final class Consent {
    /** Raised whenever the disclosure changes in a way that needs a new confirmation. */
    static final int VERSION = 2;

    static final String DISCLOSURE =
            "RelayBridge получает содержание новых SMS и номер отправителя, события входящих звонков и номер звонящего, название, заголовок и текст уведомлений выбранных приложений — только для включённых вами источников. При отдельно выданном доступе к контактам приложение локально ищет имя по номеру нового SMS или звонка и добавляет это имя в пересылаемое событие. Адресная книга целиком не копируется и не отправляется. Без доступа передаётся номер и статус «Неизвестный отправитель». Доступ к уведомлениям технически позволяет Android передавать все уведомления; RelayBridge фильтрует их по вашему выбору." + "\n\n"
            + "После включения пересылки эти данные отправляются автоматически, в том числе когда экран приложения закрыт: через Telegram Bot API в заданный ChatID и/или через указанный SMTP-сервер получателям email. Данные могут содержать личную переписку и коды. Проверьте получателей и права доступа к боту." + "\n\n"
            + "Содержание локальной очереди и истории зашифровано; хранятся до 7 дней и 500 событий. Время, тип и статусы не шифруются отдельно. Соединения защищены TLS. Собственного сервера, рекламы и аналитики нет. Остановка и удаление доступны в приложении; уже отправленные копии удаляются отдельно у получателей." + "\n\n"
            + "Согласие не включает источники и не выдаёт разрешения автоматически. Их вы выбираете отдельно.";

    static final String PRIVACY =
            "RelayBridge · конфиденциальность · 05.10.2026" + "\n\n"
            + DISCLOSURE + "\n\n"
            + "Настройки и учётные данные хранятся на устройстве в зашифрованном виде Android Keystore. Облачное резервное копирование отключено. Диагностика SMTP содержит этапы и коды ответов, без паролей, токенов и текста писем. Копирование лога происходит только по нажатию пользователя." + "\n\n"
            + "Приложение не читает старые SMS, не извлекает историю звонков или геолокацию. READ_CONTACTS используется только для поиска имени отправителя по номеру нового SMS или звонка. READ_CALL_LOG нужен Android для номера входящего звонка. READ_PHONE_STATE нужен для события звонка и определения SIM. Список выбора приложений ограничен видимыми Android приложениями и никуда отдельно не отправляется." + "\n\n"
            + "Telegram и почтовые провайдеры обрабатывают переданные сообщения по своим правилам. RelayBridge не управляет их хранением, доступом и удалением. Возможны задержки фоновых заданий и скрытие чувствительного содержимого системой." + "\n\n"
            + "В разделе Журнал можно очистить историю либо отозвать согласие и удалить все локальные настройки и данные. Системные разрешения отзываются в настройках Android. Приложение не создаёт собственного аккаунта пользователя.";

    private Consent() { }

    static boolean accepted(Context context) {
        return Config.prefs(context).getInt("consent-version", 0) == VERSION;
    }
}
